import { chromium } from "playwright"
const ws = "af91555d-7450-4b21-a8ac-73db092617c8"
const browser = await chromium.launch()
for (const [name, w, h] of [["1440", 1440, 900], ["390", 390, 844]]) {
  const page = await browser.newPage({ viewport: { width: w, height: h } })
  await page.goto(`http://localhost:3000/workspaces/${ws}/invoices`, { waitUntil: "networkidle" })
  const trigger = page.locator("tbody tr button, tbody tr [role=button], tbody tr a").first()
  await trigger.click().catch(() => {})
  await page.waitForTimeout(2500)
  await page.screenshot({ path: `/tmp/scratch229/234-pane-${name}.png` })
  const boxes = await page.evaluate(() => {
    const pane = document.getElementById("queue-detail-pane")
    const out = []
    const rect = (el) => { const r = el.getBoundingClientRect(); return { y: Math.round(r.y), h: Math.round(r.height) } }
    if (!pane) return ["no pane"]
    out.push({ paneHeader: rect(pane.querySelector("header")) })
    const inner = pane.querySelectorAll(":scope > div > div > div > div")
    inner.forEach((el, i) => { if (i < 4) out.push({ [`inner${i}`]: rect(el), cls: el.className.slice(0, 60) }) })
    const ol = pane.querySelector("ol[aria-label='Document lifecycle']")
    if (ol) out.push({ stepper: rect(ol) })
    const firstField = pane.querySelector("form input, form textarea")
    if (firstField) out.push({ firstField: rect(firstField) })
    const del = [...pane.querySelectorAll("button")].find((b) => b.textContent.trim() === "Delete")
    if (del) out.push({ delete: rect(del) })
    return out
  })
  console.log(name, JSON.stringify(boxes))
  await page.close()
}
await browser.close()

